/// An operation (it changes the scan, kept in the control file) or an analysis (it returns results).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct OperationEntry {
    /// The control file's `op = "…"`, or the analysis's function.
    pub id: &'static str,
    pub name: &'static str,
    /// "operation" or "analysis".
    pub kind: &'static str,
    pub meaning: &'static str,
    /// How the standard deviations follow.
    pub sigma: &'static str,
    /// The definition followed (paper, program) and the test that checks it.
    pub source: &'static str,
    pub settings: &'static [Setting],
}

/// A setting of an operation or analysis.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Setting {
    /// The control file's key, or the argument.
    pub key: &'static str,
    pub name: &'static str,
    pub unit: &'static str,
    pub meaning: &'static str,
    /// What the core accepts.
    pub range: &'static str,
    /// What the core takes when it is absent ("required" when nothing).
    pub default: &'static str,
    /// How a value is proposed to the user.
    pub proposed: &'static str,
    /// What a larger value does; empty when it tunes nothing.
    pub raise: &'static str,
    /// What a smaller value does.
    pub lower: &'static str,
    pub source: &'static str,
}

